"""Synthetic identifiers for generated fixtures (D3 §12). Every value here is made up.

Fixtures are generated by code at test time and never derived from real files. The NMI has no `I` or `O`, as in
real NMIs, and its checksum digit is computed, so a filename helper never builds an invalid name by accident.
"""

from collections.abc import Sequence
from typing import Final

from energatron.core.canonical import JSONValue
from energatron.core.models.private import PrivateConfig
from energatron.core.privacy import nmi_checksum

SYNTHETIC_NMI: Final = "ZZTEST0001"
"""A made-up 10-character NMI, as a NEM12 `200` record holds it."""

SYNTHETIC_NMI11: Final = f"{SYNTHETIC_NMI}{nmi_checksum(SYNTHETIC_NMI)}"
"""The same NMI with its checksum digit, as SAPN filenames hold it."""

SYNTHETIC_SERIAL: Final = "SYN0000001"
SYNTHETIC_ACCOUNT: Final = "900000000001"
SYNTHETIC_SALT: Final = "0123456789abcdef0123456789abcdef"


def synthetic_private_document(
    *,
    nmi: str = SYNTHETIC_NMI11,
    meter_serials: Sequence[str] = (SYNTHETIC_SERIAL,),
    electricity_accounts: Sequence[str] = (SYNTHETIC_ACCOUNT,),
    gas_accounts: Sequence[str] = (),
) -> dict[str, JSONValue]:
    """A `private_config` document matching the synthetic identifiers; the arguments override them."""
    return {
        "kind": "private_config",
        "schema_version": 1,
        "salt": SYNTHETIC_SALT,
        "premises": {"nmi": nmi, "meter_serials": list(meter_serials)},
        "accounts": {"electricity": list(electricity_accounts), "gas": list(gas_accounts)},
    }


def synthetic_private_config(
    *,
    nmi: str = SYNTHETIC_NMI11,
    meter_serials: Sequence[str] = (SYNTHETIC_SERIAL,),
    electricity_accounts: Sequence[str] = (SYNTHETIC_ACCOUNT,),
    gas_accounts: Sequence[str] = (),
) -> PrivateConfig:
    """A `PrivateConfig` matching the synthetic identifiers; the arguments override them."""
    return PrivateConfig.from_document(
        synthetic_private_document(
            nmi=nmi,
            meter_serials=meter_serials,
            electricity_accounts=electricity_accounts,
            gas_accounts=gas_accounts,
        )
    )
